// DIZZY — three uneven legs, one eye, and a spiral it cannot stop looking at.
//   STRIKE   (attack)        the long hooked right leg whips out; the hook tip is the sweet spot.
//   GIMMICK  (special)       HYPNO SPIRAL: a short pulse that leaves anyone near the spiral stumbling.
//   RECOVERY (up + special)  three legs spin like a wonky rotor, drifting diagonally.
//   GRAB     (grab)          the hook foot snags them, spins and flings them dizzy.
export default function make(api) {
  const { hb, cap, key, mv, throwMove, spawnProjectile, spriteAnims, spriteLoops, B, sinDeg } = api;

  const stats = {
    weight: 84, walk: 2.6, run: 4.8, dashInit: 5.6, airSpeed: 3.6, airAccel: 0.16,
    fallSpeed: 5.4, fastFall: 8.5, gravity: 0.34, shortHop: 7, fullHop: 11.5, doubleJump: 11,
    jumps: 2, wallJump: false, traction: 0.42, height: 94, width: 44, crouchHeight: 60, landLag: 5, ledgeReach: 34,
  };

  const P = (extra) => ({ a: {}, ...extra });
  const rest = P({});
  const strikePoses = (total, hit, lean, extra = {}) => [
    key(0, P({ rot: -lean * 0.5, sx: 0.95, sy: 1.05, ...extra })),
    key(hit, P({ rot: lean, sx: 1.1, sy: 0.93, ...extra })),
    key(Math.min(total - 1, hit + 6), P({ rot: lean * 0.8, sx: 1.04, sy: 0.98, ...extra })),
    key(total, rest),
  ];
  const LEG = { fx: 'hit' };
  const TIP = { fx: 'tip', priority: 0 };

  // THE STRIKE: leg from the hip to the hooked foot, as drawn in atk-fwd / atk-up / atk-down.
  const STRIKE = { total: 30, hit: 9, active: 4, damage: 10, r: 9 };
  const LEGS = {
    f: { start: [16, -34], end: [46, -36], angle: 40, lean: 12, cell: 'atk-fwd' },
    b: { start: [-16, -34], end: [-46, -36], angle: 40, lean: -14, cell: 'atk-fwd' },
    u: { start: [18, -40], end: [6, -78], angle: 86, lean: -8, cell: 'atk-up', extra: { dy: -4 } },
    d: { start: [4, -26], end: [8, -2], angle: 38, lean: 4, cell: 'atk-down', extra: { sy: 1.06 } },
  };
  const aim = (id, dir, opts = {}) => {
    const s = { ...STRIKE, ...opts };
    const L = LEGS[dir];
    const frames = [s.hit, s.hit + s.active - 1];
    const base = s.base ?? 38, growth = s.growth ?? 82;
    return mv(id, s.total, [
      hb(frames, L.end[0], L.end[1], s.r + 2, s.damage + 3, L.angle, base + 4, growth + 6, { ...TIP, ...(s.hb ?? {}) }),
      cap(frames, L.start[0], L.start[1], L.end[0], L.end[1], s.r, s.damage, L.angle, base, growth, { ...LEG, priority: 1, ...(s.hb ?? {}) }),
    ], strikePoses(s.total, s.hit, L.lean, L.extra ?? {}), { cell: L.cell, cellFlip: dir === 'b', ...(s.mv ?? {}) });
  };

  // Dizzy: other fighters by slot, frames of stumbling left. Their input is not ours, so onFrame pushes them around.
  const SLOTS = 8;
  const dizzy = (state, f, cx, cy, r, t) => {
    if (state.fighters.length > SLOTS) throw new Error('DIZZY: more fighters than dizzy slots');
    let hit = false;
    state.fighters.forEach((o, i) => {
      if (o === f) return;
      const dx = o.x - cx, dy = (o.y - 40) - cy;
      if (dx * dx + dy * dy <= r * r) { f.special['dz' + i] = Math.max(f.special['dz' + i], t); hit = true; }
    });
    return hit;
  };
  const spiral = (f) => [f.x + f.moveFacing * 18, f.y - 51];

  const GRAB = { total: 34, hit: 8, damage: 8 };
  const toss = (id, angle, base, growth, pose) => ({
    ...throwMove(id, 34, 16, GRAB.damage, angle, base, growth, [key(0, P({ rot: 8 })), key(8, P({ rot: -20, sx: 1.08 })), key(16, P(pose)), key(34, rest)]),
    hook: 'fling',
  });

  const moves = {
    jab1: aim('jab1', 'f', { total: 22, hit: 6, damage: 6, mv: { iasa: 17 } }),
    ftilt: aim('ftilt', 'f'),
    dashAttack: aim('dashAttack', 'f', { total: 36, hit: 9, damage: 10, mv: { motion: [[1, 6, 0], [12, 3, 0], [20, 1, 0]] } }),
    nair: aim('nair', 'f', { total: 28, hit: 7, damage: 8, mv: { aerial: true, landingLag: 9 } }),
    fair: aim('fair', 'f', { mv: { aerial: true, landingLag: 11 } }),
    bair: aim('bair', 'b', { damage: 11, mv: { aerial: true, landingLag: 12 } }),
    utilt: aim('utilt', 'u', { damage: 9 }),
    uair: aim('uair', 'u', { damage: 9, mv: { aerial: true, landingLag: 10 } }),
    dtilt: aim('dtilt', 'd', { damage: 8 }),
    dair: aim('dair', 'd', { total: 38, hit: 13, damage: 11, hb: { spike: true }, mv: { aerial: true, landingLag: 16 } }),
    // charged: wound way back, cracked like a scythe
    fsmash: mv('fsmash', 52, [
      hb([16, 19], 48, -36, 12, 20, 38, 44, 100, TIP),
      cap([16, 20], 16, -34, 46, -36, 10, 15, 40, 40, 84, { ...LEG, priority: 1 }),
    ], [key(0, P({ rot: -18, sx: 0.92, sy: 1.06 })), key(15, P({ rot: -24, sx: 0.9 })), key(16, P({ rot: 22, sx: 1.16, sy: 0.9 })), key(26, P({ rot: 16 })), key(52, rest)], { smash: true, cell: 'atk-fwd' }),
    usmash: aim('usmash', 'u', { total: 50, hit: 15, active: 6, damage: 15, base: 42, growth: 98, mv: { smash: true } }),
    dsmash: mv('dsmash', 54, [
      hb([16, 19], 8, -4, 18, 15, 30, 44, 88, { ...LEG, group: 0 }),
      hb([24, 27], 8, -4, 26, 11, 30, 44, 80, { fx: 'quake', group: 1 }),
    ], [key(0, P({ dy: -10, sy: 1.1 })), key(16, P({ dy: 0, sy: 0.84, sx: 1.12 })), key(24, P({ sy: 0.9, sx: 1.08 })), key(54, rest)], { smash: true, cell: 'atk-down' }),
    grab: mv('grab', GRAB.total, [hb([GRAB.hit, GRAB.hit + 2], 44, -38, 14, 0, 0, 0, 0, { grab: true })], strikePoses(GRAB.total, GRAB.hit, 12), { isGrab: true, cell: 'atk-fwd' }),
    dashGrab: mv('dashGrab', 40, [hb([9, 11], 50, -38, 15, 0, 0, 0, 0, { grab: true })], strikePoses(40, 9, 18), { isGrab: true, cell: 'atk-fwd', motion: [[1, 5, 0], [9, 0, 0]] }),
    pummel: mv('pummel', 16, [], [key(0, P({ rot: 6 })), key(6, P({ rot: 14, sx: 1.06 })), key(16, P({ rot: 6 }))], { cell: 'atk-fwd' }),
    fthrow: toss('fthrow', 42, 58, 72, { rot: 28, sx: 1.1 }),
    bthrow: toss('bthrow', 40, 62, 80, { rot: -40 }),
    uthrow: toss('uthrow', 88, 66, 88, { dy: -12, sy: 1.14 }),
    dthrow: toss('dthrow', 70, 44, 40, { sy: 0.82, sx: 1.14, dy: 12 }),
    // GIMMICK, HYPNO SPIRAL: short, slow pulse; only dizzies when the spiral is rested (see cool)
    nspecial: mv('nspecial', 50, [hb([20, 25], 18, -51, 34, 5, 60, 30, 50, { fx: 'energy' })], [key(0, P({ sy: 0.94 })), key(18, P({ rot: -8, sx: 1.06 })), key(20, P({ rot: 6, sx: 1.12, sy: 1.08 })), key(32, P({ rot: 2 })), key(50, rest)], { hook: 'pulse', cell: 'block', fx: 'guard' }),
    // held sideways: the spiral peels off and rolls forward
    sspecial: mv('sspecial', 44, [], strikePoses(44, 14, 14), { hook: 'peel', cell: 'atk-fwd' }),
    // held down: the spiral spins in place; hit it and you stare into it
    dspecial: mv('dspecial', 44, [], [key(0, rest), key(5, P({ sy: 0.9, sx: 1.06 })), key(26, P({ sy: 0.9, sx: 1.06, rot: 4 })), key(44, rest)], { counter: { frames: [5, 26], move: 'hypnoCounter', mul: 1.2, min: 6 }, cell: 'block', fx: 'guard' }),
    hypnoCounter: mv('hypnoCounter', 34, [hb([3, 6], 18, -51, 40, 8, 50, 45, 70, { fx: 'energy' })], [key(0, P({ sx: 1.14, sy: 0.9 })), key(6, P({ sx: 1.04 })), key(34, rest)], { hook: 'stare', cell: 'block' }),
    // RECOVERY, LEG ROTOR
    uspecial: mv('uspecial', 56, [cap([4, 12], -24, -10, 24, -10, 16, 6, 80, 40, 60, LEG)], [key(0, P({ sy: 0.86, sx: 1.1 })), key(4, P({ sy: 1.1, rot: -10 })), key(14, P({ rot: 12 })), key(24, P({ rot: -12 })), key(34, P({ rot: 10 })), key(56, P({ rot: -6 }))], { hook: 'rotor', helpless: true, ledgeOk: true, cell: 'jump' }),
    ledgeAttack: aim('ledgeAttack', 'f', { total: 38, hit: 12, damage: 8 }),
    getupAttack: mv('getupAttack', 42, [cap([12, 15], 10, -30, 46, -36, 10, 7, 45, 40, 60, { ...LEG, group: 0 }), cap([20, 23], -10, -30, -46, -36, 10, 7, 45, 40, 60, { ...LEG, group: 1 })], [key(0, rest), key(12, P({ rot: 14 })), key(20, P({ rot: -14 })), key(42, rest)], { cell: 'atk-fwd' }),
    taunt: mv('taunt', 50, [], [key(0, rest), key(12, P({ rot: -12, sy: 1.08 })), key(26, P({ rot: 12, sy: 1.08 })), key(50, rest)], { cell: 'walk' }),
  };

  const specialInit = { cool: 0, bx: 0, by: 0, bvx: 0, bt: 0 };
  for (let i = 0; i < SLOTS; i++) specialInit['dz' + i] = 0;

  return {
    id: 'dizzy',
    name: 'DIZZY',
    tagline: 'Three legs, one eye, and a spiral it cannot stop looking at.',
    stats,
    moves,
    rig: { bones: [], anims: spriteAnims(), loops: spriteLoops },
    palette: { colors: { marker: '#c7352b', dots: '#1f8a86' }, accent: 'dots', outline: '#1d1d1b' },
    special: () => ({ ...specialInit }),
    hooks: {
      pulse: ({ state, f }) => {
        if (f.frame === 20 && f.special.cool <= 0) {
          const [cx, cy] = spiral(f);
          dizzy(state, f, cx, cy, 44, 110);
          f.special.cool = 240;
        }
      },
      peel: ({ state, f }) => {
        if (f.frame === 14 && f.special.cool <= 0) {
          const [cx, cy] = spiral(f);
          const vx = f.moveFacing * 3.2;
          spawnProjectile(state, f, 'spiral', cx, cy, vx, 0, 100,
            { frames: [0, 999], x: 0, y: 0, r: 12, damage: 6, angle: 45, base: 30, growth: 35, fx: 'energy' }, { g: 0 });
          f.special.bx = cx; f.special.by = cy; f.special.bvx = vx; f.special.bt = 100;
          f.special.cool = 300;
        }
      },
      stare: ({ state, f }) => {
        if (f.frame === 3) { const [cx, cy] = spiral(f); dizzy(state, f, cx, cy, 70, 150); }
      },
      fling: ({ state, f }) => {
        if (f.frame === 2) dizzy(state, f, f.x, f.y - 40, 80, 90);
      },
      rotor: ({ f, input }) => {
        if (f.frame === 4) { f.grounded = false; f.platform = -1; f.usedUpSpecial = true; }
        if (f.frame >= 4 && f.frame <= 40) {
          f.vy = -6.6 + (f.frame - 4) * 0.15;
          f.vx = (input.x / 100) * 5 + f.moveFacing * 0.8 + sinDeg(f.frame * 30) * 0.6;
        }
      },
    },
    onFrame: ({ state, f }) => {
      const s = f.special;
      if (s.cool > 0) s.cool--;
      if (s.bt > 0) {
        s.bx += s.bvx; s.bt--;
        if (dizzy(state, f, s.bx, s.by, 24, 110)) s.bt = 0;
      }
      for (let i = 0; i < SLOTS; i++) {
        const t = s['dz' + i];
        if (t <= 0) continue;
        s['dz' + i] = t - 1;
        const o = state.fighters[i];
        if (!o || o === f || Math.abs(o.vx) > 6) continue;
        if (o.grounded) o.vx = o.vx * 0.55 + sinDeg(t * 11) * 2.4;
        else o.vx += sinDeg(t * 11) * 0.3;
      }
    },
    meters: [{ label: 'SPIRAL', color: '#1f8a86', get: (f) => 1 - f.special.cool / 300 }],
    visual: (f) => ({ glow: f.special.cool > 0 ? 0 : 0.5 }),
  };
}
